  const candidates = order
    .filter((id) => earliest[id].finish === totalDuration)
    .map((id) => bestPathById.get(id)!)
    .sort(comparePaths);

  return {
    order,
    layers,
    earliest,
    totalDuration,
    criticalPath: candidates[0] ?? [],
  };
}

